WITH enriched AS (SELECT *, MIN(pressure) OVER (PARTITION BY device_code ORDER BY humidity, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_min_pressure, MAX(pressure) OVER (PARTITION BY device_code ORDER BY humidity, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_max_pressure, SUM(pressure) OVER (PARTITION BY device_code ORDER BY humidity, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_sum_pressure, AVG(pressure) OVER (PARTITION BY device_code ORDER BY humidity, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_avg_pressure FROM device_readings) SELECT id, reading_ts, status_bits, firmware, running_min_pressure, running_max_pressure, running_sum_pressure, running_avg_pressure FROM enriched
